def find_zombie_twin(system, x):
    if not system.has_qualia(x):
        return None
    for y in system.states:
        if system.func_equiv(x, y) and not system.has_qualia(y):
            return y
    return None

def measure_gap(system):
    classes = {}
    for s in system.states:
        c = system.equiv_classes[s]
        classes.setdefault(c, []).append(s)
    mixed = sum(1 for states in classes.values()
                if any(system.has_qualia(s) for s in states)
                and any(not system.has_qualia(s) for s in states))
    return mixed / len(classes)

def check_respects(pred, system):
    for x in system.states:
        for y in system.states:
            if system.func_equiv(x, y) and pred(x) != pred(y):
                return False
    return True
